// Real captured card artwork: TCGdex me01-001 and sv02-185 low.webp (245 × 337).
const BULBASAUR_ART = Buffer.from(
  "",
  "base64"
);
const IONO_ART = Buffer.from(
  "",
  "base64"
);

async function prepare(page: Page, blockArt?: () => void) {
  (await artUpstream()).reset();
  execFileSync(
    ".venv/bin/python",
    ["-c", "from test_catalog_browse import seed_popup\nseed_popup()"],
    {
      env: { ...process.env, PYTHONPATH: "api:api/tests" },
    }
  );
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
  try {
    await startAsNewOwner(pool);
    await pool.query("DELETE FROM auth_send_event");
  } finally {
    await pool.end();
  }
  if (blockArt) await page.clock.install();
  await page.route("**/api/art/**", (route) => {
    if (blockArt) {
      if (route.request().url().includes("/large")) blockArt();
      return route.abort();
    }
    return route.fulfill({ contentType: "image/webp", body: BULBASAUR_ART });
  });
  await signInAsOwner(page, "/catalog");
}

async function observe(page: Page) {
  await page.evaluate(() => {
    const messages: string[] = [];
    const last = new WeakMap<Element, string>();
    const selector =
      '[role="status"], [role="alert"], [aria-live], #app-toasts';
    document
      .querySelectorAll(selector)
      .forEach((el) => last.set(el, el.textContent ?? ""));
    new MutationObserver(() => {
      document.querySelectorAll(selector).forEach((el) => {
        const text = (
          (el.id === "app-toasts"
            ? el.querySelector("p")?.textContent
            : el.textContent) ?? ""
        ).trim();
        if (last.get(el) === text) return;
        last.set(el, text);
        if (el.closest('[aria-live="off"]')) return;
        if (
          /^(Added |Undo removed|Undo may not|This Edition is no longer available)/.test(
            text
          )
        )
          messages.push(text);
      });
      document.documentElement.dataset.dialogAnnouncements =
        JSON.stringify(messages);
    }).observe(document.body, {
      subtree: true,
      childList: true,
      characterData: true,
    });
  });
}

