function seedIllustratedCatalog(): Record<string, string> {
  const output = execFileSync(
    ".venv/bin/python",
    [
      "-c",
      `
import want_list_swap_fixtures as fixture
fixture.SWAP_CARDS = tuple({**card, "image": "https://assets.tcgdex.net/en/sv/" + card["set"]["id"] + "/" + card["localId"]} if card["category"] == "Trainer" else card for card in fixture.SWAP_CARDS)
fixture.print_swap_catalog()
`,
    ],
    { env: { ...process.env, PYTHONPATH: "api:api/tests" } }
  ).toString();
  return JSON.parse(output.slice(output.lastIndexOf("SWAP") + 4));
}

async function checkLargerArt(
  page: Page,
  dialog: import("@playwright/test").Locator,
  info: import("@playwright/test").TestInfo,
  label: string
) {
  const art = dialog.locator("img").first();
  await expect
    .poll(() =>
      art.evaluate(
        (img) =>
          (img as HTMLImageElement).complete &&
          (img as HTMLImageElement).naturalWidth > 0
      )
    )
    .toBe(true);
  const trigger = dialog.getByRole("button", {
    name: /^View larger image of /,
  });
  if (page.viewportSize()!.width > 760) {
    await expect(trigger).toHaveCount(0);
    await expect.poll(() => art.evaluate((img) => img.clientWidth)).toBe(176);
    return;
  }
  await expectTouchTarget(trigger);
  await expect
    .poll(() => trigger.evaluate((el) => el.clientWidth))
    .toBeGreaterThanOrEqual(112);
  await info.attach(`${label}-thumbnail`, {
    body: await page.screenshot(),
    contentType: "image/png",
  });
  await info.attach(`${label}-thumbnail-measurements`, {
    body: JSON.stringify(await trigger.boundingBox()),
    contentType: "application/json",
  });
  await trigger.click();
  const enlarged = page.locator("dialog[open]").last();
  const large = enlarged.locator("img");
  await expect
    .poll(() =>
      large.evaluate(
        (img) =>
          (img as HTMLImageElement).complete &&
          (img as HTMLImageElement).naturalWidth > 0
      )
    )
    .toBe(true);
  await expect
    .poll(() =>
      large.evaluate((img) => {
        const box = img.parentElement!;
        const style = getComputedStyle(box);
        return (
          img.clientWidth ===
          box.clientWidth -
            parseFloat(style.paddingLeft) -
            parseFloat(style.paddingRight)
        );
      })
    )
    .toBe(true);
  const close = enlarged.getByRole("button", { name: "Close", exact: true });
  await expectTouchTarget(close);
  await info.attach(`${label}-expanded`, {
    body: await page.screenshot(),
    contentType: "image/png",
  });
  await close.click();
  await expect(trigger).toBeFocused();
  await trigger.press("Enter");
  await page
    .locator("dialog[open]")
    .last()
    .getByRole("button", { name: "Close", exact: true })
    .press("Escape");
  await expect(trigger).toBeFocused();
}

for (const phone of [false, true]) {
  test.describe(`pending Undo row ownership ${phone ? "phone" : "desktop"}`, () => {
    test.use({
      viewport: phone
        ? { width: 375, height: 812 }
        : { width: 1280, height: 800 },
      isMobile: phone,
      hasTouch: phone,
      deviceScaleFactor: phone ? 2 : 1,
    });
    for (const transition of ["close-reopen", "card", "edition"]) {
      for (const fails of [false, true]) {
        test(`${transition}: pending Undo ${fails ? "failure" : "success"} is announced exactly once`, async ({
          page,
        }) => {
          await prepare(page);
          const opener = page
            .getByRole("region", { name: "Catalog results" })
            .getByRole("button", { name: /^Bulbasaur,/ })
            .first();
          await opener.click();
          const dialog = page.getByRole("dialog");
          await dialog
            .getByRole("button", { name: "Add 1", exact: true })
            .click();
          await expect(
            dialog.getByRole("button", { name: "Undo", exact: true })
          ).toBeVisible();
          let release!: () => void;
          const held = new Promise<void>((resolve) => {
            release = resolve;
          });
          let arrived!: () => void;
          const started = new Promise<void>((resolve) => {
            arrived = resolve;
          });
          await page.route("**/api/moves/undo/*", async (route) => {
            if (route.request().method() !== "POST") return route.continue();
            arrived();
            await held;
            if (fails)
              await route.fulfill({
                status: 503,
                json: { detail: { code: "TEMPORARY" } },
              });
            else await route.continue();
          });
          await observe(page);
          await dialog
            .getByRole("button", { name: "Undo", exact: true })
            .click();
          await started;
          if (transition === "close-reopen") {
            await dialog
              .getByRole("button", { name: "Close card details", exact: true })
              .click();
            await opener.click();
          } else if (transition === "card") {
            await dialog
              .getByRole("button", { name: "Next card", exact: true })
              .click();
            await dialog
              .getByRole("button", { name: "Next card", exact: true })
              .click();
            await expect(dialog).toHaveAccessibleName("Rare Candy");
          } else {
            await dialog
              .getByRole("group", { name: "Editions" })
              .getByRole("button", { name: /^Reverse Holo/ })
              .click();
          }
          release();
          const text = fails
            ? "Undo may not have finished. Try again to check safely."
            : "Undo removed 1 card from Unsorted.";
          await expect(page.locator("#app-toasts")).toContainText(text);
          await expect(page.locator("#app-toasts")).toHaveAttribute(
            "aria-live",
            "polite"
          );
          await expect(
            dialog.getByRole("status").filter({ hasText: text })
          ).toHaveCount(0);
          await expect
            .poll(async () =>
              JSON.parse(
                (await page
                  .locator("html")
                  .getAttribute("data-dialog-announcements")) ?? "[]"
              )
            )
            .toEqual([text]);
        });
      }
    }
  });
  test.describe(`Published Deck artwork ${phone ? "phone" : "desktop"}`, () => {
    test.use({
      viewport: phone
        ? { width: 375, height: 812 }
        : { width: 1280, height: 800 },
      isMobile: phone,
      hasTouch: phone,
    });
    test("real artwork can be enlarged and dismissed", async ({
      page,
    }, info) => {
      await prepare(page);
      const owner = await accountId(page);
      const output = execFileSync(
        ".venv/bin/python",
        [
          "-c",
          "import json, sys\nfrom test_published_deck_page import page_world\nprint(json.dumps(page_world(sys.argv[1], 'Artwork')))",
          owner,
        ],
        { env: { ...process.env, PYTHONPATH: "api:api/tests" } }
      ).toString();
      const world = JSON.parse(output.trim().split("\n").at(-1)!);
      await page.route(/^https:\/\/assets\.tcgdex\.net\//, (route) =>
        route.fulfill({ contentType: "image/webp", body: BULBASAUR_ART })
      );
      await page.goto(new URL(`/published/${world.Legal}`, page.url()).href);
      await page
        .getByRole("radiogroup", { name: "Deck List view" })
        .getByRole("radio", { name: "List", exact: true })
        .click();
      await page
        .getByRole("region", { name: "Deck List" })
        .getByRole("listitem")
        .filter({ hasText: "Bulbasaur" })
        .getByRole("button")
        .click();
      const dialog = page.getByRole("dialog", {
        name: "Bulbasaur",
        exact: true,
      });
      await checkLargerArt(page, dialog, info, "Published Deck");
      await expectPageChecks(page, "Published Deck real artwork");
    });
  });
}
